import { createFileRoute } from "@tanstack/react-router";
import { Database, Leaf, Mountain, Network, ShieldCheck, Sun, TriangleAlert } from "lucide-react";
import { SectionHeading, StatusBadge, Surface } from "@/components/halisia/ds";
import {
  getResourceFoundationStatus,
  type ResourceFoundationStatus,
} from "@/lib/resource-intelligence.functions";

// The checked-in TanStack route tree is regenerated by the Vite router plugin.
// Cast this newly added route only until that generated file refreshes during build.
export const Route = createFileRoute("/resource-intelligence" as never)({
  loader: () => getResourceFoundationStatus(),
  head: () => ({
    meta: [
      { title: "Resource Intelligence — HALISIA AI" },
      {
        name: "description",
        content:
          "HALISIA Resource Intelligence foundation for land, agriculture, minerals, energy and evidence provenance.",
      },
      { name: "robots", content: "noindex,nofollow" },
    ],
  }),
  component: ResourceIntelligencePage,
});

const domains = [
  {
    title: "LAND",
    icon: Mountain,
    detail: "Existing HALISIA parcel, terrain, infrastructure and land-intelligence foundation.",
    state: "Live foundation",
  },
  {
    title: "LIMAR",
    icon: Leaf,
    detail: "Agriculture, climate, soil and water intelligence. Authoritative dataset adapters are next.",
    state: "Foundation only",
  },
  {
    title: "MADINI",
    icon: Database,
    detail: "Minerals, geology and mining intelligence with explicit occurrence/resource/reserve separation.",
    state: "Foundation only",
  },
  {
    title: "ENERGY",
    icon: Sun,
    detail: "Shared solar, wind, geothermal, grid and storage evidence layer for LAND, LIMAR and MADINI.",
    state: "Foundation only",
  },
] as const;

function ResourceIntelligencePage() {
  const status = Route.useLoaderData() as ResourceFoundationStatus;
  const coreEnabled =
    status.flags.find((flag) => flag.key === "resource_intelligence")?.enabled ?? false;
  const evidenceEnabled =
    status.flags.find((flag) => flag.key === "evidence_graph")?.enabled ?? false;

  return (
    <main
      className="mx-auto min-h-dvh w-full max-w-6xl px-4 pb-20 pt-24 sm:px-6"
      data-testid="resource-intelligence-status"
    >
      <Surface elevation={3} padding="lg">
        <div className="flex flex-wrap items-start justify-between gap-4">
          <SectionHeading
            as="h1"
            eyebrow="Evidence-first platform foundation"
            title="Resource Intelligence"
            description="One evidence model for LAND, LIMAR, MADINI and ENERGY. Missing evidence stays missing; AI inference can never become regulator verification."
          />
          <StatusBadge kind={status.ok ? "verified" : "pending"}>
            {status.ok ? "Database connected" : "Database unavailable"}
          </StatusBadge>
        </div>
        <div className="kenya-rule mt-5" />
        <div className="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
          <Metric label="Registered sources" value={status.counts.sources} />
          <Metric label="Observations" value={status.counts.observations} />
          <Metric label="Assessments" value={status.counts.assessments} />
          <Metric label="Evidence links" value={status.counts.evidenceLinks} />
        </div>
        {!status.ok && (
          <div className="mt-4 flex items-start gap-2 rounded-2xl border border-amber-glow/30 bg-amber-glow/10 p-3 text-sm text-muted-foreground">
            <TriangleAlert
              className="mt-0.5 h-4 w-4 shrink-0 text-amber-glow"
              aria-hidden="true"
            />
            <span>
              The UI shell is available, but the server could not read the Resource Intelligence
              tables. No scores or evidence are fabricated while the data connection is
              unavailable.
            </span>
          </div>
        )}
      </Surface>

      <section className="mt-6 grid gap-4 md:grid-cols-2" aria-label="Resource domains">
        {domains.map(({ title, icon: Icon, detail, state }) => (
          <Surface key={title} elevation={2} padding="md" className="h-full">
            <div className="flex items-start justify-between gap-3">
              <span className="grid h-11 w-11 place-items-center rounded-2xl bg-primary/10 text-primary">
                <Icon className="h-5 w-5" aria-hidden="true" />
              </span>
              <StatusBadge kind={title === "LAND" ? "verified" : "pending"}>{state}</StatusBadge>
            </div>
            <h2 className="mt-4 text-xl font-semibold">{title}</h2>
            <p className="mt-2 text-sm leading-relaxed text-muted-foreground">{detail}</p>
          </Surface>
        ))}
      </section>

      <section className="mt-6 grid gap-4 lg:grid-cols-[1.2fr_0.8fr]">
        <Surface elevation={2} padding="md">
          <div className="flex items-center gap-2">
            <Network className="h-5 w-5 text-primary" aria-hidden="true" />
            <h2 className="font-semibold">Evidence graph readiness</h2>
          </div>
          <p className="mt-2 text-sm text-muted-foreground">
            Conclusions are designed to trace through assessments, observations, sources, methods
            and confidence. The evidence graph remains disabled until real observations are loaded
            and validated.
          </p>
          <div className="mt-4 grid gap-2 sm:grid-cols-2">
            <Flag label="Resource Intelligence" enabled={coreEnabled} />
            <Flag label="Evidence Graph" enabled={evidenceEnabled} />
          </div>
        </Surface>

        <Surface elevation={2} padding="md">
          <div className="flex items-center gap-2">
            <ShieldCheck className="h-5 w-5 text-primary" aria-hidden="true" />
            <h2 className="font-semibold">Truth rules active</h2>
          </div>
          <ul className="mt-3 space-y-2 text-sm text-muted-foreground">
            <li>• Model output cannot self-promote beyond INFERRED.</li>
            <li>• Regulator verification requires a regulator-class source.</li>
            <li>• Insufficient evidence cannot publish a numeric readiness score.</li>
            <li>• All new sector modules default OFF until evidence adapters pass.</li>
          </ul>
        </Surface>
      </section>

      <Surface elevation={2} padding="md" className="mt-6">
        <h2 className="font-semibold">Current execution gate</h2>
        <p className="mt-2 text-sm text-muted-foreground">
          M0-A proves the shared evidence and verification foundation. The next controlled
          milestone is the Konza/Kajiado LIMAR + ENERGY pilot, using source-backed observations
          only. MADINI follows on the same evidence backbone after that pilot is proven end to end.
        </p>
      </Surface>
    </main>
  );
}

function Metric({ label, value }: { label: string; value: number }) {
  return (
    <div className="rounded-2xl border border-white/10 bg-white/5 p-4">
      <div className="text-2xl font-semibold tracking-tight">{value}</div>
      <div className="mt-1 text-xs text-muted-foreground">{label}</div>
    </div>
  );
}

function Flag({ label, enabled }: { label: string; enabled: boolean }) {
  return (
    <div className="flex items-center justify-between gap-3 rounded-xl border border-white/10 px-3 py-2">
      <span className="text-sm">{label}</span>
      <StatusBadge kind={enabled ? "verified" : "pending"}>
        {enabled ? "Enabled" : "Off"}
      </StatusBadge>
    </div>
  );
}
